'use strict';
const $=s=>document.querySelector(s), KEY='aocr-maggie-demo-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let docs, active=null, page=1, dirty=false, view='scan', toastTimer;
const blobs=new Map();
try{docs=JSON.parse(localStorage.getItem(KEY))||structuredClone(window.AOCR_SEED);}catch{docs=structuredClone(window.AOCR_SEED);}
function toast(s){$('#toast').textContent=s;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').textContent='',5000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(docs));return true;}catch{toast('Browser storage is unavailable. Changes remain in this session only.');return false;}}
function canLeave(){if(!dirty)return true;if(!confirm('Discard unsaved changes?'))return false;dirty=false;return true;}
function show(id){['library','review','upload'].forEach(x=>$('#'+x).hidden=x!==id);window.scrollTo(0,0);}
function sources(){const old=$('#source').value;$('#source').innerHTML='<option value="">All sources</option>'+[...new Set(docs.map(d=>d.archive))].sort().map(a=>`<option>${esc(a)}</option>`).join('');$('#source').value=old;}
function list(){const q=$('#query').value.trim().toLowerCase(),from=$('#from').value,to=$('#to').value,source=$('#source').value,location=$('#location').value.toLowerCase().trim();
 const filtered=docs.filter(d=>{const text=[d.title,d.archive,d.location,...d.tags,...d.blocks.map(b=>b.corrected_text??b.original_text)].join(' ').toLowerCase();return (!q||text.includes(q))&&(!from||(d.date&&d.date>=from))&&(!to||(d.date&&d.date<=to))&&(!source||d.archive===source)&&(!location||d.location.toLowerCase().includes(location));});
 $('#count').textContent=from&&to&&from>to?'Start date must be on or before end date.':`${filtered.length} document${filtered.length===1?'':'s'} found`;
 $('#cards').innerHTML=filtered.map(d=>`<article class="card">${d.base?`<img class="card-image" src="${esc(d.base)}.png" alt="First-page scan of ${esc(d.title)}">`:'<div class="card-image" aria-label="PDF awaiting processing"></div>'}<div class="card-body"><span class="badge ${d.processing_status==='awaiting_backend'?'warn':''}">${d.processing_status==='awaiting_backend'?'Awaiting backend connection':d.review_status==='reviewed'?'Sample excerpts reviewed':'Ready for review'}</span><h2>${esc(d.title)}</h2><p class="muted">${esc(d.date||'Date not specified')} · ${esc(d.location||'Location not specified')}</p><p class="fine">${esc(d.archive)}</p><button data-open="${esc(d.id)}">Open document →</button></div></article>`).join('')||'<div class="empty">No documents match these filters. Try a broader search.</div>';
 $('[id=cards]').querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openDoc(b.dataset.open));}
function openDoc(id){if(!canLeave())return;active=docs.find(d=>d.id===id);page=1;view='scan';renderReview();show('review');}
function renderReview(){const d=active,blocks=d.blocks.filter(b=>b.page===page),url=d.file||blobs.get(d.id),img=d.base?`${d.base}${page===1?'':'-p'+page}.png`:null;
 $('#review').innerHTML=`<button class="back secondary" id="back">← Collection</button><div class="heading"><div><p class="eyebrow">DOCUMENT WORKSPACE</p><h1>${esc(d.title)}</h1><p class="muted">${esc(d.date||'Date unknown')} · ${esc(d.location)} · Revision ${d.revision}</p></div>${url?`<a class="button secondary" href="${esc(url)}" target="_blank" rel="noopener">Open original PDF ↗</a>`:''}</div>
 ${d.processing_status==='awaiting_backend'?'<div class="document-notice">PDF added locally. No OCR request has been sent. Processing status will come from the backend after integration.</div>':'<div class="document-notice">Review sample: selected first-page excerpts only. Sample confidence and suggestions are illustrative. Full-document OCR has not been run.</div>'}
 <div class="review-grid"><div class="panel"><div class="toolbar"><label>Page <select id="page" ${d.pages?'':'disabled'}>${Array.from({length:d.pages||1},(_,i)=>`<option value="${i+1}" ${page===i+1?'selected':''}>${d.pages?i+1:'Unknown'}</option>`).join('')}</select></label><button id="scan-view" class="${view==='scan'?'':'secondary'}" aria-pressed="${view==='scan'}">Scan</button><button id="text-view" class="${view==='text'?'':'secondary'}" aria-pressed="${view==='text'}">Text</button></div>${view==='scan'?`<div class="scan-wrap">${img?`<img src="${esc(img)}" alt="Original scan, page ${page} of ${esc(d.title)}">`:url?`<iframe title="Local PDF preview" src="${esc(url)}"></iframe>`:'<p>Reselect the PDF below to restore this session’s preview.</p>'}</div>`:`<div class="page-text">${blocks.length?blocks.map(b=>esc(b.corrected_text??b.original_text)).join('\n\n'):'No demo transcription is supplied for this page.'}</div>`}${!d.base?'<label class="review-meta">Restore or replace local PDF preview<input id="reselect" type="file" accept="application/pdf,.pdf"></label>':''}</div>
 <div><section class="panel"><h2>Review transcription</h2><p class="fine">Compare every proposed change with the scan. Original text is retained.</p>${blocks.length?blocks.map(b=>`<div class="block" data-block="${esc(b.id)}"><h3>${esc(b.label)}</h3><p class="fine">Sample engine confidence: ${b.confidence===null?'unavailable':Math.round(b.confidence*100)+'% (illustrative)'}</p><details><summary>Original sample text</summary><p class="original">${esc(b.original_text)}</p></details><label style="margin-top:12px">Reviewed text<textarea data-text="${esc(b.id)}">${esc(b.corrected_text??b.original_text)}</textarea></label>${b.suggestion?`<div class="suggestion"><strong>Suggested correction</strong><br>${esc(b.suggestion.text)}<p>${esc(b.suggestion.reason)}</p><span class="fine">Decision: ${esc(b.suggestion.resolution)}</span><br><button class="secondary" data-accept="${esc(b.id)}">Use suggestion</button><button class="secondary" data-reject="${esc(b.id)}">Reject suggestion</button></div>`:''}<button data-save="${esc(b.id)}">Save changes</button><details style="margin-top:12px"><summary>Revision history (${b.history.length})</summary>${b.history.map(h=>`<div class="revision">${esc(h.at)} · Demo reviewer<br>${esc(h.text)}<br>Suggestion: ${esc(h.resolution||'none')}</div>`).join('')||'<p class="fine">No saved changes yet.</p>'}</details></div>`).join(''):'<div class="empty">No extracted text is available for this page. OCR results will populate this area after backend integration.</div>'}<div class="actions"><button class="secondary" id="export" ${!d.blocks.length?'disabled':''}>Download text excerpts</button><button class="secondary" id="complete" ${!d.blocks.length?'disabled':''}>Mark sample excerpts reviewed</button></div><p class="fine" id="review-state">Review state: ${d.review_status==='reviewed'?'sample excerpts reviewed':'pending'}</p></section>
 <details class="panel review-meta"><summary>Edit document metadata</summary><form id="metadata"><div class="form-grid"><label>Title<input name="title" required maxlength="200" value="${esc(d.title)}"></label><label>Publication date<input name="date" type="date" value="${esc(d.date)}"></label><label>Source / archive<input name="archive" required maxlength="150" value="${esc(d.archive)}"></label><label>Location<input name="location" maxlength="150" value="${esc(d.location)}"></label><label>Tags (comma separated)<input name="tags" value="${esc(d.tags.join(', '))}"></label></div><button>Save changes</button></form></details></div></div>`;
 $('#back').onclick=()=>{if(canLeave()){sources();list();show('library');}};
 $('#page').onchange=e=>{if(canLeave()){page=Number(e.target.value);renderReview();}else e.target.value=page;};
 $('#scan-view').onclick=()=>{if(canLeave()){view='scan';renderReview();}};$('#text-view').onclick=()=>{if(canLeave()){view='text';renderReview();}};
 $('#review').querySelectorAll('textarea,input').forEach(el=>el.oninput=()=>dirty=true);
 $('#review').querySelectorAll('[data-accept]').forEach(el=>el.onclick=()=>{const b=d.blocks.find(x=>x.id===el.dataset.accept);$(`[data-text="${b.id}"]`).value=b.suggestion.text;el.closest('.suggestion').querySelector('span').textContent='Decision: accept on save';el.closest('.block').dataset.resolution='accepted';dirty=true;toast('Suggestion applied to draft. Save correction to keep it.');});
 $('#review').querySelectorAll('[data-reject]').forEach(el=>el.onclick=()=>{el.closest('.block').dataset.resolution='rejected';el.closest('.suggestion').querySelector('span').textContent='Decision: reject on save';dirty=true;toast('Rejection selected. Save correction to keep the decision.');});
 function saveChanges(){
  const meta=$('#metadata');if(!meta.reportValidity())return;if(!meta.elements.title.value.trim()||!meta.elements.archive.value.trim()){toast('Enter a title and source containing text.');return;}
  const edits=[...$('#review').querySelectorAll('[data-text]')];
  if(edits.some(el=>!el.value.trim())){toast('Reviewed text cannot be empty in this demo.');return;}
  let changed=false;
  for(const el of edits){const b=d.blocks.find(x=>x.id===el.dataset.text),value=el.value.trim(),resolution=el.closest('.block').dataset.resolution||b.suggestion?.resolution;
   if(value!==(b.corrected_text??b.original_text)||resolution!==b.suggestion?.resolution){b.corrected_text=value;if(b.suggestion)b.suggestion.resolution=resolution;b.history.unshift({at:new Date().toISOString(),text:value,resolution});changed=true;}
  }
  const form=new FormData(meta);['title','date','archive','location'].forEach(k=>d[k]=form.get(k).trim());d.tags=form.get('tags').split(',').map(s=>s.trim()).filter(Boolean);
  if(changed)d.review_status='pending';d.revision++;const saved=persist();dirty=false;renderReview();toast(saved?'All changes saved in this browser.':'Changes kept for this session only.');
 }
 $('#review').querySelectorAll('[data-save]').forEach(el=>el.onclick=saveChanges);
 $('#export').onclick=()=>{if(!canLeave())return;const text=`${d.title}\nSample excerpts only — not a complete OCR transcript.\n\n`+d.blocks.map(b=>`Page ${b.page}: ${b.corrected_text??b.original_text}`).join('\n\n');download(d.id+'-reviewed-excerpts.txt',text);};
 $('#complete').onclick=()=>{if(!canLeave())return;if(d.blocks.some(b=>b.suggestion?.resolution==='pending')){toast('Resolve and save each pending suggestion before marking reviewed.');return;}d.review_status='reviewed';d.revision++;persist();renderReview();toast('Sample excerpts marked reviewed. Full-document review is still outside this demo.');};
 $('#metadata').onsubmit=e=>{e.preventDefault();saveChanges();};
 if($('#reselect'))$('#reselect').onchange=async e=>{const f=e.target.files[0];if(!f)return;const error=await validatePDF(f);if(error){toast(error);return;}if(blobs.has(d.id))URL.revokeObjectURL(blobs.get(d.id));blobs.set(d.id,URL.createObjectURL(f));dirty=false;renderReview();};
}
async function validatePDF(file){if(file.size>25*1024*1024)return 'Choose a PDF no larger than 25 MiB.';if(!file.name.toLowerCase().endsWith('.pdf'))return 'Choose a file with a .pdf extension.';if(!(await file.slice(0,5).text()).startsWith('%PDF-'))return 'This file does not have a PDF signature. Choose a valid PDF.';return '';}
function download(name,text){const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('#filters').oninput=list;$('#filters').onchange=list;$('#filters').onreset=()=>setTimeout(list,0);
$('#add').onclick=()=>{if(canLeave()){show('upload');$('#title').focus();}};$('#cancel-upload').onclick=()=>show('library');$('#home').onclick=e=>{e.preventDefault();if(canLeave()){sources();list();show('library');}};
$('#upload-form').onsubmit=async e=>{e.preventDefault();const f=$('#file').files[0];if(!f)return;const error=await validatePDF(f);$('#upload-error').textContent=error;if(error)return;if(!$('#title').value.trim()||!$('#archive').value.trim()){$('#upload-error').textContent='Enter a title and source containing text.';return;}const id='local-'+crypto.randomUUID();const d={id,title:$('#title').value.trim(),date:$('#date').value,archive:$('#archive').value.trim(),location:$('#place').value.trim(),tags:[],file:null,base:null,pages:null,processing_status:'awaiting_backend',review_status:'pending',revision:1,blocks:[]};docs.unshift(d);blobs.set(id,URL.createObjectURL(f));persist();e.target.reset();sources();list();openDoc(id);toast('PDF added locally. Backend upload and OCR are pending integration.');};
$('#reset').onclick=()=>{if(!confirm('Remove local demo edits and added document records, and restore the two original samples?'))return;docs=structuredClone(window.AOCR_SEED);persist();dirty=false;for(const u of blobs.values())URL.revokeObjectURL(u);blobs.clear();sources();list();show('library');toast('Demo data reset.');};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue='';}});sources();list();
